package chain

import (
	stderrors "errors"
	"fmt"
	"os"
	"sync"

	"github.com/pkg/errors"

	"github.com/zenon-network/go-zenon/chain/cache/storage"
	"github.com/zenon-network/go-zenon/chain/momentum"
	"github.com/zenon-network/go-zenon/chain/store"
	"github.com/zenon-network/go-zenon/common"
	"github.com/zenon-network/go-zenon/common/db"
	"github.com/zenon-network/go-zenon/common/types"
)

var (
	inserterLog = common.ChainLogger.New("submodule", "chain-insert-mutex")
)

type chain struct {
	log common.Logger

	store.Genesis
	*accountPool
	*momentumPool
	*momentumEventManager
	*chainCache
	*stateTree

	chainManager db.Manager
	cacheManager storage.CacheManager
	insert       sync.Mutex
	lifecycle    sync.Mutex
	stopped      bool
}

func NewChain(chainManager db.Manager, cacheManager storage.CacheManager, genesis store.Genesis, stateTreeDir string, stateTreeArchive bool) *chain {
	momentumPool := NewMomentumPool(chainManager, genesis)
	cache := NewChainCache(cacheManager)
	return &chain{
		log:                  common.ChainLogger,
		Genesis:              genesis,
		accountPool:          newAccountPool(momentumPool),
		momentumPool:         momentumPool,
		momentumEventManager: momentumPool.momentumEventManager,
		chainCache:           cache,
		stateTree:            newStateTree(stateTreeDir, stateTreeArchive),
		chainManager:         chainManager,
		cacheManager:         cacheManager,
	}
}

func (c *chain) Init() error {
	c.lifecycle.Lock()
	defer c.lifecycle.Unlock()
	if c.stopped {
		return errors.New("chain instance is stopped")
	}

	c.log.Info("initializing ...")
	defer c.log.Info("initialized")

	// Read the selected ledger metadata before logging or registering listeners.
	// A missing row must not make an existing ledger look empty, and aligned
	// cache/tree metadata alone cannot validate the stored momentum body.
	frontierDB := c.chainManager.Frontier()
	if frontierDB == nil {
		return errors.New("can't initialize chain: ledger-unavailable")
	}
	if c.cacheManager.DB() == nil {
		return errors.New("can't initialize chain: cache-unavailable")
	}
	frontierStore := momentum.NewStore(c.Genesis, frontierDB)
	expectedFrontier := db.GetFrontierIdentifier(frontierDB)
	frontier, err := frontierStore.GetFrontierMomentum()
	if err != nil {
		return err
	}
	if !expectedFrontier.IsZero() {
		if frontier == nil {
			return errors.New("can't initialize chain: missing-frontier")
		}
		if frontier.Identifier() != expectedFrontier {
			return errors.New("can't initialize chain: frontier-identifier-mismatch")
		}
		if frontier.ComputeHash() != expectedFrontier.Hash {
			return errors.New("can't initialize chain: frontier-body-hash-mismatch")
		}
	}

	c.log.Info("starting chain module with db", "location", c.chainManager.Location(), "frontier-identifier", expectedFrontier)

	// check if the configured genesis matches the existent chain
	if err := c.checkGenesisCompatibility(); err != nil {
		return err
	}
	types.SporkAddress = c.genesis.GetSporkAddress()
	c.Register(c.accountPool)
	// Prime the pool's pricing context from the committed frontier so the
	// first contested insert after start-up is priced the same way as one
	// arriving after the next momentum, rather than falling back to the
	// legacy comparator until then.
	c.accountPool.refreshDynamicPlasma()

	frontierStore = c.GetFrontierMomentumStore()
	frontier, err = frontierStore.GetFrontierMomentum()
	if err != nil {
		return err
	}
	if frontier == nil {
		return errors.New("can't initialize chain: missing-frontier")
	}

	if err := c.chainCache.Init(c.chainManager, frontierStore); err != nil {
		return err
	}

	if err := c.stateTree.Init(c.chainManager, frontierStore); err != nil {
		return err
	}

	fmt.Printf("Initialized NoM. Height: %v, Hash: %v\n", frontier.Height, frontier.Hash)
	c.log.Info("initialized nom", "identifier", frontier.Identifier())

	if _, unimplemented, err := GotAllActiveSporksImplemented(frontierStore); err != nil {
		return err
	} else if unimplemented != nil {
		c.log.Crit("can't start node because don't have all sporks implemented",
			"hash", frontier.Hash, "height", frontier.Height, "unimplemented", unimplemented)

		fmt.Printf("===== Error =====\n")
		fmt.Printf("Can't start node. %v height %v\n", frontier.Hash, frontier.Height)
		fmt.Printf("Detected an unimplemented spork.\n")
		for _, spork := range unimplemented {
			fmt.Printf("  Spork name `%v` id:`%v`\n", spork.Name, spork.Id)
		}
		fmt.Printf("\n")
		fmt.Printf("Please upgrade your znnd binary\n")
		fmt.Printf("znnd is terminating\n")
		os.Exit(2)
	}

	return nil
}
func (c *chain) Start() error {
	c.lifecycle.Lock()
	defer c.lifecycle.Unlock()
	if c.stopped {
		return errors.New("chain instance is stopped")
	}

	c.log.Info("starting ...")
	defer c.log.Info("started")

	c.stateTree.startBuild(c)

	return nil
}
func (c *chain) Stop() error {
	c.lifecycle.Lock()
	defer c.lifecycle.Unlock()
	if c.stopped {
		return nil
	}
	c.stopped = true

	c.log.Info("stopping ...")
	defer c.log.Info("stopped")

	c.UnRegister(c.accountPool)

	// Every manager is stopped whatever the earlier ones report: a manager
	// marks itself stopped even when its Close fails, so bailing out on the
	// first error would leave the remaining handles open until exit. The
	// caller sees every error that occurred.
	return stderrors.Join(c.stateTree.stop(), c.cacheManager.Stop(), c.chainManager.Stop())
}

func (c *chain) checkGenesisCompatibility() error {
	frontierStore := c.GetFrontierMomentumStore()
	if frontierStore.Identifier().IsZero() {
		insert := c.AcquireInsert("add genesis momentum")
		defer insert.Unlock()
		c.log.Info("did not find any blocks. Inserting genesis block")
		// chain is empty, apply genesis
		if err := c.momentumPool.AddMomentumTransaction(insert, c.GetGenesisTransaction()); err != nil {
			return err
		}
	} else {
		genesisMomentum, err := frontierStore.GetMomentumByHeight(1)
		if err != nil {
			return err
		}
		if genesisMomentum == nil {
			return errors.New("can't initialize chain: missing-genesis")
		}
		if genesisMomentum.Identifier() != c.GetGenesisMomentum().Identifier() {
			return errors.Errorf("The genesis state is incorrect. " +
				"You can fix the problem by removing the database manually.")
		}
		if genesisMomentum.ComputeHash() != genesisMomentum.Hash {
			return errors.New("can't initialize chain: genesis-body-hash-mismatch")
		}
		c.log.Info("found momentums in DB. genesis-hash matches")
	}
	return nil
}

// GetCacheStore resolves the complete identifier in the current ledger before
// creating the cache's height-indexed view. Cache values remain excluded from
// the partial state commitment. The caller still owns history serialization.
func (c *chain) GetCacheStore(identifier types.HashHeight) store.Cache {
	if c == nil || c.chainManager == nil || c.chainCache == nil {
		return nil
	}
	frontierDB := c.chainManager.Frontier()
	if frontierDB == nil {
		return nil
	}
	selected, err := momentum.NewStore(c.Genesis, frontierDB).GetMomentumByHeight(identifier.Height)
	if err != nil || selected == nil || selected.Identifier() != identifier {
		return nil
	}
	return c.chainCache.GetCacheStore(identifier)
}

func (c *chain) AcquireInsert(reason string) sync.Locker {
	inserterLog.Debug("waiting", "reason", reason)
	c.insert.Lock()

	inserterLog.Debug("acquired", "reason", reason)
	return &inserter{
		reason: reason,
		mutex:  &c.insert,
	}
}

type inserter struct {
	reason string
	mutex  *sync.Mutex
}

func (i *inserter) Lock() {
	panic("can't lock an insert - already locked")
}
func (i *inserter) Unlock() {
	inserterLog.Debug("released", "reason", i.reason)
	i.mutex.Unlock()
	i.mutex = nil
}

